&lt;!DOCTYPE html&gt;&lt;html lang&#x3D;&quot;en&quot;&gt;&lt;head&gt; &lt;meta charset&#x3D;&quot;UTF-8&quot;&gt; &lt;meta name&#x3D;&quot;viewport&quot; content&#x3D;&quot;width&#x3D;device-width,initial-scale&#x3D;1,shrink-to-fit&#x3D;no&quot;&gt; &lt;title&gt;高级的CSS组件&lt;&#x2F;title&gt; &lt;!– Bootstrap核心css文件–&gt; &lt;link rel&#x3D;&quot;stylesheet&quot; href&#x3D;&quot;https://cdn.bootcss.com/twitter-bootstrap/4.4.1/css/bootstrap.min.css&quot;&gt;
&lt;&#x2F;head&gt;&lt;body class&#x3D;&quot;container&quot;&gt;&lt;h3 class&#x3D;&quot;mb-4&quot;&gt;背景和文字颜色&lt;&#x2F;h3&gt;&lt;ul class&#x3D;&quot;list-group list-group-flush&quot;&gt; &lt;li class&#x3D;&quot;list-group-item list-group-item-primary&quot;&gt;全心全力 见心见行&lt;&#x2F;li&gt; &lt;li class&#x3D;&quot;list-group-item list-group-item-secondary&quot;&gt;同心同德 启帆远航&lt;&#x2F;li&gt; &lt;li class&#x3D;&quot;list-group-item list-group-item-success&quot;&gt;同心同行 共创未来&lt;&#x2F;li&gt; &lt;li class&#x3D;&quot;list-group-item list-group-item-danger&quot;&gt;激情闪耀 共创辉煌&lt;&#x2F;li&gt; &lt;li class&#x3D;&quot;list-group-item list-group-item-warning&quot;&gt;超越梦想 再创辉煌&lt;&#x2F;li&gt; &lt;li class&#x3D;&quot;list-group-item list-group-item-info&quot;&gt;飞跃巅峰 纵横四海&lt;&#x2F;li&gt; &lt;li class&#x3D;&quot;list-group-item list-group-item-light&quot;&gt;融合梦想 努力超越&lt;&#x2F;li&gt; &lt;li class&#x3D;&quot;list-group-item list-group-item-dark&quot;&gt;超越第一 实现梦想&lt;&#x2F;li&gt;&lt;&#x2F;ul&gt;&lt;!–引入js文件–&gt;&lt;script src&#x3D;&quot;https://code.jquery.com/jquery-3.3.1.slim.min.js&quot;&gt;&lt;/script&gt;&lt;script src&#x3D;&quot;https://cdnjs.cloudflare.com/ajax/libs/popper.js/1.14.6/umd/popper.min.js&quot;&gt;&lt;/script&gt;&lt;!–Bootstrap核心JavaScript文件–&gt;&lt;script src&#x3D;&quot;https://cdn.bootcss.com/twitter-bootstrap/4.4.1/js/bootstrap.min.js&quot;&gt;&lt;/script&gt;&lt;&#x2F;body&gt;&lt;&#x2F;html&gt;
