&lt;!DOCTYPE html&gt;&lt;html lang&#x3D;&quot;en&quot;&gt;&lt;head&gt; &lt;meta charset&#x3D;&quot;UTF-8&quot;&gt; &lt;meta name&#x3D;&quot;viewport&quot; content&#x3D;&quot;width&#x3D;device-width,initial-scale&#x3D;1,shrink-to-fit&#x3D;no&quot;&gt; &lt;title&gt;高级的CSS组件&lt;&#x2F;title&gt; &lt;!– Bootstrap核心css文件–&gt; &lt;link rel&#x3D;&quot;stylesheet&quot; href&#x3D;&quot;https://cdn.bootcss.com/twitter-bootstrap/4.4.1/css/bootstrap.min.css&quot;&gt;
