&lt;&#x2F;ul&gt;&lt;!–引入js文件–&gt;&lt;script src&#x3D;&quot;https://code.jquery.com/jquery-3.3.1.slim.min.js&quot;&gt;&lt;/script&gt;&lt;script src&#x3D;&quot;https://cdnjs.cloudflare.com/ajax/libs/popper.js/1.14.6/umd/popper.min.js&quot;&gt;&lt;/script&gt;&lt;!–Bootstrap核心JavaScript文件–&gt;&lt;script src&#x3D;&quot;https://cdn.bootcss.com/twitter-bootstrap/4.4.1/js/bootstrap.min.js&quot;&gt;&lt;/script&gt;&lt;&#x2F;body&gt;&lt;&#x2F;html&gt;
定制内容复杂的列表项：可以在列表项中嵌入更多内容，如标题、文本、徽章等，以实现更复杂的布局。
&lt;!DOCTYPE html&gt;&lt;html lang&#x3D;&quot;en&quot;&gt;&lt;head&gt; &lt;meta charset&#x3D;&quot;UTF-8&quot;&gt; &lt;meta name&#x3D;&quot;viewport&quot; content&#x3D;&quot;width&#x3D;device-width,initial-scale&#x3D;1,shrink-to-fit&#x3D;no&quot;&gt; &lt;title&gt;高级的CSS组件&lt;&#x2F;title&gt; &lt;!– Bootstrap核心css文件–&gt; &lt;link rel&#x3D;&quot;stylesheet&quot; href&#x3D;&quot;https://cdn.bootcss.com/twitter-bootstrap/4.4.1/css/bootstrap.min.css&quot;&gt;
&lt;&#x2F;head&gt;&lt;body class&#x3D;&quot;container&quot;&gt;&lt;h3 class&#x3D;&quot;mb-4&quot;&gt;定制内容&lt;&#x2F;h3&gt;&lt;h5&gt;招聘信息&lt;&#x2F;h5&gt;&lt;div class&#x3D;&quot;list-group&quot;&gt; &lt;a href&#x3D;&quot;#&quot; class&#x3D;&quot;list-group-item list-group-item-action active&quot;&gt; &lt;div class&#x3D;&quot;d-flex w-100 justify-content-between&quot;&gt; &lt;h5 class&#x3D;&quot;mb-1&quot;&gt;公司名称&lt;&#x2F;h5&gt; &lt;small&gt;发布时间&lt;&#x2F;small&gt; &lt;&#x2F;div&gt; &lt;p class&#x3D;&quot;mb-1&quot;&gt;描述&lt;&#x2F;p&gt; &lt;p&gt;薪资&lt;&#x2F;p&gt; &lt;&#x2F;a&gt; &lt;a href&#x3D;&quot;#&quot; class&#x3D;&quot;list-group-item list-group-item-action&quot;&gt; &lt;div class&#x3D;&quot;d-flex w-100 justify-content-between&quot;&gt; &lt;h5 class&#x3D;&quot;mb-1&quot;&gt;顺畅建筑有限公司&lt;&#x2F;h5&gt; &lt;small class&#x3D;&quot;text-muted&quot;&gt;一天前&lt;&#x2F;small&gt; &lt;&#x2F;div&gt; &lt;p class&#x3D;&quot;mb-1&quot;&gt;公司在全国各地都有项目，现招一位项目经理，工作地点在新疆。。。&lt;&#x2F;p&gt; &lt;p&gt;10-15k&lt;&#x2F;p&gt; &lt;&#x2F;a&gt; &lt;a href&#x3D;&quot;#&quot; class&#x3D;&quot;list-group-item list-group-item-action&quot;&gt; &lt;div class&#x3D;&quot;d-flex w-100 justify-content-between&quot;&gt; &lt;h5 class&#x3D;&quot;mb-1&quot;&gt;梦想网络有限公司&lt;&#x2F;h5&gt; &lt;small class&#x3D;&quot;text-muted&quot;&gt;一天前&lt;&#x2F;small&gt; &lt;&#x2F;div&gt; &lt;p class&#x3D;&quot;mb-1&quot;&gt;本公司位于北京，现招一位web前端工程师，要求有两年以上工作经验。。。&lt;&#x2F;p&gt; &lt;p&gt;8-12k&lt;&#x2F;p&gt; &lt;&#x2F;a&gt;
&lt;&#x2F;div&gt;&lt;!–引入js文件–&gt;&lt;script src&#x3D;&quot;https://code.jquery.com/jquery-3.3.1.slim.min.js&quot;&gt;&lt;/script&gt;&lt;script src&#x3D;&quot;https://cdnjs.cloudflare.com/ajax/libs/popper.js/1.14.6/umd/popper.min.js&quot;&gt;&lt;/script&gt;&lt;!–Bootstrap核心JavaScript文件–&gt;&lt;script src&#x3D;&quot;https://cdn.bootcss.com/twitter-bootstrap/4.4.1/js/bootstrap.min.js&quot;&gt;&lt;/script&gt;&lt;&#x2F;body&gt;&lt;&#x2F;html&gt;
面包屑面包屑导航是一种用户界面元素，通常用于显示用户在网站或应用程序中的位置路径。它提供了层次结构的上下文，并允许用户轻松地返回到上一层或更高层级的页面。
定义面包屑面包屑在 Bootstrap 中使用 .breadcrumb 类来创建。每个导航项使用 &amp;lt;li&amp;gt; 元素，并带有 .breadcrumb-item 类。最后一个项通常代表当前页面，使用 .active 类标记。
&lt;!DOCTYPE html&gt;&lt;html lang&#x3D;&quot;en&quot;&gt;&lt;head&gt; &lt;meta charset&#x3D;&quot;UTF-8&quot;&gt; &lt;meta name&#x3D;&quot;viewport&quot; content&#x3D;&quot;width&#x3D;device-width,initial-scale&#x3D;1,shrink-to-fit&#x3D;no&quot;&gt; &lt;title&gt;高级的CSS组件&lt;&#x2F;title&gt; &lt;!– Bootstrap核心css文件–&gt; &lt;link rel&#x3D;&quot;stylesheet&quot; href&#x3D;&quot;https://cdn.bootcss.com/twitter-bootstrap/4.4.1/css/bootstrap.min.css&quot;&gt;
&lt;&#x2F;head&gt;&lt;body class&#x3D;&quot;container&quot;&gt;&lt;h3 class&#x3D;&quot;mb-4&quot;&gt;面包屑&lt;&#x2F;h3&gt;&lt;nav aria-label&#x3D;&quot;breadcrumb&quot;&gt; &lt;ol class&#x3D;&quot;breadcrumb&quot;&gt; &lt;li class&#x3D;&quot;breadcrumb-item active&quot;&gt;首页&lt;&#x2F;li&gt; &lt;&#x2F;ol&gt;&lt;&#x2F;nav&gt;&lt;nav aria-label&#x3D;&quot;breadcrumb&quot;&gt; &lt;ol class&#x3D;&quot;breadcrumb&quot;&gt; &lt;li class&#x3D;&quot;breadcrumb-item&quot;&gt;&lt;a href&#x3D;&quot;#&quot;&gt;首页&lt;&#x2F;a&gt;&lt;&#x2F;li&gt; &lt;li class&#x3D;&quot;breadcrumb-item active&quot;&gt;图书馆&lt;&#x2F;li&gt; &lt;&#x2F;ol&gt;&lt;&#x2F;nav&gt;&lt;nav aria-label&#x3D;&quot;breadcrumb&quot;&gt; &lt;ol class&#x3D;&quot;breadcrumb&quot;&gt; &lt;li class&#x3D;&quot;breadcrumb-item&quot;&gt;&lt;a href&#x3D;&quot;#&quot;&gt;首页&lt;&#x2F;a&gt;&lt;&#x2F;li&gt; &lt;li class&#x3D;&quot;breadcrumb-item&quot;&gt;&lt;a href&#x3D;&quot;#&quot;&gt;图书馆&lt;&#x2F;a&gt;&lt;&#x2F;li&gt; &lt;li class&#x3D;&quot;breadcrumb-item active&quot;&gt;工程类&lt;&#x2F;li&gt; &lt;&#x2F;ol&gt;&lt;&#x2F;nav&gt;
&lt;!–引入js文件–&gt;&lt;script src&#x3D;&quot;https://code.jquery.com/jquery-3.3.1.slim.min.js&quot;&gt;&lt;/script&gt;&lt;script src&#x3D;&quot;https://cdnjs.cloudflare.com/ajax/libs/popper.js/1.14.6/umd/popper.min.js&quot;&gt;&lt;/script&gt;&lt;!–Bootstrap核心JavaScript文件–&gt;&lt;script src&#x3D;&quot;https://cdn.bootcss.com/twitter-bootstrap/4.4.1/js/bootstrap.min.js&quot;&gt;&lt;/script&gt;&lt;&#x2F;body&gt;&lt;&#x2F;html&gt;


关键点：.breadcrumb 类用于定义整个面包屑导航的容器。.breadcrumb-item 类用于定义每个面包屑导航项。.active 类用于标记当前页面所在的导航项。
设计分隔符默认分隔符：在 Bootstrap 中，面包屑导航项之间的默认分隔符是斜杠 (&#x2F;)。这个分隔符可以通过 CSS 自定义。
自定义分隔符：如果你想要更改分隔符，可以使用 CSS。比如，将分隔符改为 &gt;：
&lt;!DOCTYPE html&gt;&lt;html lang&#x3D;&quot;en&quot;&gt;&lt;head&gt; &lt;meta charset&#x3D;&quot;UTF-8&quot;&gt; &lt;meta name&#x3D;&quot;viewport&quot; content&#x3D;&quot;width&#x3D;device-width,initial-scale&#x3D;1,shrink-to-fit&#x3D;no&quot;&gt; &lt;title&gt;高级的CSS组件&lt;&#x2F;title&gt; &lt;!– Bootstrap核心css文件–&gt; &lt;link rel&#x3D;&quot;stylesheet&quot; href&#x3D;&quot;https://cdn.bootcss.com/twitter-bootstrap/4.4.1/css/bootstrap.min.css&quot;&gt; &lt;style&gt; .breadcrumb-item + .breadcrumb-item::before&#123; display: inline-block; padding-right: 0.5rem; color: #6c757d; content: &#x27;&gt;&#x27;; &#125; &lt;&#x2F;style&gt;&lt;&#x2F;head&gt;&lt;body class&#x3D;&quot;container&quot;&gt;&lt;h3 class&#x3D;&quot;mb-4&quot;&gt;面包屑&lt;&#x2F;h3&gt;&lt;nav aria-label&#x3D;&quot;breadcrumb&quot;&gt; &lt;ol class&#x3D;&quot;breadcrumb&quot;&gt; &lt;li class&#x3D;&quot;breadcrumb-item active&quot;&gt;首页&lt;&#x2F;li&gt; &lt;&#x2F;ol&gt;&lt;&#x2F;nav&gt;&lt;nav aria-label&#x3D;&quot;breadcrumb&quot;&gt; &lt;ol class&#x3D;&quot;breadcrumb&quot;&gt; &lt;li class&#x3D;&quot;breadcrumb-item&quot;&gt;&lt;a href&#x3D;&quot;#&quot;&gt;首页&lt;&#x2F;a&gt;&lt;&#x2F;li&gt; &lt;li class&#x3D;&quot;breadcrumb-item active&quot;&gt;图书馆&lt;&#x2F;li&gt; &lt;&#x2F;ol&gt;&lt;&#x2F;nav&gt;&lt;nav aria-label&#x3D;&quot;breadcrumb&quot;&gt; &lt;ol class&#x3D;&quot;breadcrumb&quot;&gt; &lt;li class&#x3D;&quot;breadcrumb-item&quot;&gt;&lt;a href&#x3D;&quot;#&quot;&gt;首页&lt;&#x2F;a&gt;&lt;&#x2F;li&gt; &lt;li class&#x3D;&quot;breadcrumb-item&quot;&gt;&lt;a href&#x3D;&quot;#&quot;&gt;图书馆&lt;&#x2F;a&gt;&lt;&#x2F;li&gt; &lt;li class&#x3D;&quot;breadcrumb-item active&quot;&gt;工程类&lt;&#x2F;li&gt; &lt;&#x2F;ol&gt;&lt;&#x2F;nav&gt;
&lt;!–引入js文件–&gt;&lt;script src&#x3D;&quot;https://code.jquery.com/jquery-3.3.1.slim.min.js&quot;&gt;&lt;/script&gt;&lt;script src&#x3D;&quot;https://cdnjs.cloudflare.com/ajax/libs/popper.js/1.14.6/umd/popper.min.js&quot;&gt;&lt;/script&gt;&lt;!–Bootstrap核心JavaScript文件–&gt;&lt;script src&#x3D;&quot;https://cdn.bootcss.com/twitter-bootstrap/4.4.1/js/bootstrap.min.js&quot;&gt;&lt;/script&gt;&lt;&#x2F;body&gt;&lt;&#x2F;html&gt;
分页分页（pagination）是用于指示一系列相关的内容存在于多个页面中的组件
定义分页分页是一种导航方法，用于将大量内容分成多个页面，以便用户可以轻松浏览。通常用于长列表、搜索结果或文章目录等。分页组件通常包含页码链接、”上一页” 和 “下一页” 按钮等，允许用户在内容中快速跳转。
&lt;!DOCTYPE html&gt;&lt;html lang&#x3D;&quot;en&quot;&gt;&lt;head&gt; &lt;meta charset&#x3D;&quot;UTF-8&quot;&gt; &lt;meta name&#x3D;&quot;viewport&quot; content&#x3D;&quot;width&#x3D;device-width,initial-scale&#x3D;1,shrink-to-fit&#x3D;no&quot;&gt; &lt;title&gt;高级的CSS组件&lt;&#x2F;title&gt; &lt;!– Bootstrap核心css文件–&gt; &lt;link rel&#x3D;&quot;stylesheet&quot; href&#x3D;&quot;https://cdn.bootcss.com/twitter-bootstrap/4.4.1/css/bootstrap.min.css&quot;&gt;&lt;&#x2F;head&gt;&lt;body class&#x3D;&quot;container&quot;&gt;&lt;h3 class&#x3D;&quot;mb-4&quot;&gt;定义分页&lt;&#x2F;h3&gt;&lt;ul class&#x3D;&quot;pagination&quot;&gt; &lt;li class&#x3D;&quot;page-item&quot;&gt;&lt;a href&#x3D;&quot;#&quot; class&#x3D;&quot;page-link&quot;&gt;首页&lt;&#x2F;a&gt;&lt;&#x2F;li&gt; &lt;li class&#x3D;&quot;page-item&quot;&gt;&lt;a href&#x3D;&quot;#&quot; class&#x3D;&quot;page-link&quot;&gt;上一页&lt;&#x2F;a&gt;&lt;&#x2F;li&gt; &lt;li class&#x3D;&quot;page-item&quot;&gt;&lt;a href&#x3D;&quot;#&quot; class&#x3D;&quot;page-link&quot;&gt;1&lt;&#x2F;a&gt;&lt;&#x2F;li&gt; &lt;li class&#x3D;&quot;page-item&quot;&gt;&lt;a href&#x3D;&quot;#&quot; class&#x3D;&quot;page-link&quot;&gt;2&lt;&#x2F;a&gt;&lt;&#x2F;li&gt; &lt;li class&#x3D;&quot;page-item&quot;&gt;&lt;a href&#x3D;&quot;#&quot; class&#x3D;&quot;page-link&quot;&gt;3&lt;&#x2F;a&gt;&lt;&#x2F;li&gt; &lt;li class&#x3D;&quot;page-item&quot;&gt;&lt;a href&#x3D;&quot;#&quot; class&#x3D;&quot;page-link&quot;&gt;4&lt;&#x2F;a&gt;&lt;&#x2F;li&gt; &lt;li class&#x3D;&quot;page-item&quot;&gt;&lt;a href&#x3D;&quot;#&quot; class&#x3D;&quot;page-link&quot;&gt;5&lt;&#x2F;a&gt;&lt;&#x2F;li&gt; &lt;li class&#x3D;&quot;page-item&quot;&gt;&lt;a href&#x3D;&quot;#&quot; class&#x3D;&quot;page-link&quot;&gt;下一页&lt;&#x2F;a&gt;&lt;&#x2F;li&gt; &lt;li class&#x3D;&quot;page-item&quot;&gt;&lt;a href&#x3D;&quot;#&quot; class&#x3D;&quot;page-link&quot;&gt;尾页&lt;&#x2F;a&gt;&lt;&#x2F;li&gt;&lt;&#x2F;ul&gt;
&lt;!–引入js文件–&gt;&lt;script src&#x3D;&quot;https://code.jquery.com/jquery-3.3.1.slim.min.js&quot;&gt;&lt;/script&gt;&lt;script src&#x3D;&quot;https://cdnjs.cloudflare.com/ajax/libs/popper.js/1.14.6/umd/popper.min.js&quot;&gt;&lt;/script&gt;&lt;!–Bootstrap核心JavaScript文件–&gt;&lt;script src&#x3D;&quot;https://cdn.bootcss.com/twitter-bootstrap/4.4.1/js/bootstrap.min.js&quot;&gt;&lt;/script&gt;&lt;&#x2F;body&gt;&lt;&#x2F;html&gt;
使用图标在分页中使用图标可以让用户界面更直观和友好。Bootstrap 提供了使用 Font Awesome 或 Bootstrap Icons 等图标库的方式来增强分页导航的视觉效果。
&lt;!DOCTYPE html&gt;&lt;html lang&#x3D;&quot;en&quot;&gt;&lt;head&gt; &lt;meta charset&#x3D;&quot;UTF-8&quot;&gt; &lt;meta name&#x3D;&quot;viewport&quot; content&#x3D;&quot;width&#x3D;device-width,initial-scale&#x3D;1,shrink-to-fit&#x3D;no&quot;&gt; &lt;title&gt;高级的CSS组件&lt;&#x2F;title&gt; &lt;!– Bootstrap核心css文件–&gt; &lt;link rel&#x3D;&quot;stylesheet&quot; href&#x3D;&quot;https://cdn.bootcss.com/twitter-bootstrap/4.4.1/css/bootstrap.min.css&quot;&gt;&lt;&#x2F;head&gt;&lt;body class&#x3D;&quot;container&quot;&gt;&lt;h3 class&#x3D;&quot;mb-4&quot;&gt;使用图标&lt;&#x2F;h3&gt;&lt;ul class&#x3D;&quot;pagination&quot;&gt; &lt;li class&#x3D;&quot;page-item&quot;&gt;&lt;a href&#x3D;&quot;#&quot; class&#x3D;&quot;page-link&quot;&gt;首页&lt;&#x2F;a&gt;&lt;&#x2F;li&gt; &lt;li class&#x3D;&quot;page-item&quot;&gt;&lt;a href&#x3D;&quot;#&quot; class&#x3D;&quot;page-link&quot;&gt;&lt;span&gt;&amp;laquo;&lt;&#x2F;span&gt;&lt;&#x2F;a&gt;&lt;&#x2F;li&gt; &lt;li class&#x3D;&quot;page-item&quot;&gt;&lt;a href&#x3D;&quot;#&quot; class&#x3D;&quot;page-link&quot;&gt;1&lt;&#x2F;a&gt;&lt;&#x2F;li&gt; &lt;li class&#x3D;&quot;page-item&quot;&gt;&lt;a href&#x3D;&quot;#&quot; class&#x3D;&quot;page-link&quot;&gt;2&lt;&#x2F;a&gt;&lt;&#x2F;li&gt; &lt;li class&#x3D;&quot;page-item&quot;&gt;&lt;a href&#x3D;&quot;#&quot; class&#x3D;&quot;page-link&quot;&gt;3&lt;&#x2F;a&gt;&lt;&#x2F;li&gt; &lt;li class&#x3D;&quot;page-item&quot;&gt;&lt;a href&#x3D;&quot;#&quot; class&#x3D;&quot;page-link&quot;&gt;4&lt;&#x2F;a&gt;&lt;&#x2F;li&gt; &lt;li class&#x3D;&quot;page-item&quot;&gt;&lt;a href&#x3D;&quot;#&quot; class&#x3D;&quot;page-link&quot;&gt;5&lt;&#x2F;a&gt;&lt;&#x2F;li&gt; &lt;li class&#x3D;&quot;page-item&quot;&gt;&lt;a href&#x3D;&quot;#&quot; class&#x3D;&quot;page-link&quot;&gt;&lt;span&gt;&amp;raquo;&lt;&#x2F;span&gt;&lt;&#x2F;a&gt;&lt;&#x2F;li&gt; &lt;li class&#x3D;&quot;page-item&quot;&gt;&lt;a href&#x3D;&quot;#&quot; class&#x3D;&quot;page-link&quot;&gt;尾页&lt;&#x2F;a&gt;&lt;&#x2F;li&gt;&lt;&#x2F;ul&gt;
&lt;!–引入js文件–&gt;&lt;script src&#x3D;&quot;https://code.jquery.com/jquery-3.3.1.slim.min.js&quot;&gt;&lt;/script&gt;&lt;script src&#x3D;&quot;https://cdnjs.cloudflare.com/ajax/libs/popper.js/1.14.6/umd/popper.min.js&quot;&gt;&lt;/script&gt;&lt;!–Bootstrap核心JavaScript文件–&gt;&lt;script src&#x3D;&quot;https://cdn.bootcss.com/twitter-bootstrap/4.4.1/js/bootstrap.min.js&quot;&gt;&lt;/script&gt;&lt;&#x2F;body&gt;&lt;&#x2F;html&gt;
设计分页风格在设计分页时，除了功能外，风格也是非常重要的。不同的分页风格可以为用户带来不同的使用体验。Bootstrap 提供了几种分页样式，但你也可以通过自定义 CSS 来设计独特的分页风格。
默认风格
这是 Bootstrap 提供的默认分页样式，简洁而常见。
&lt;ul class&#x3D;&quot;pagination&quot;&gt; &lt;li class&#x3D;&quot;page-item&quot;&gt;&lt;a class&#x3D;&quot;page-link&quot; href&#x3D;&quot;#&quot;&gt;1&lt;&#x2F;a&gt;&lt;&#x2F;li&gt; &lt;li class&#x3D;&quot;page-item&quot;&gt;&lt;a class&#x3D;&quot;page-link&quot; href&#x3D;&quot;#&quot;&gt;2&lt;&#x2F;a&gt;&lt;&#x2F;li&gt; &lt;li class&#x3D;&quot;page-item&quot;&gt;&lt;a class&#x3D;&quot;page-link&quot; href&#x3D;&quot;#&quot;&gt;3&lt;&#x2F;a&gt;&lt;&#x2F;li&gt;&lt;&#x2F;ul&gt;
大小变化
Bootstrap 允许你通过添加 pagination-lg 或 pagination-sm 类来更改分页组件的大小。
&lt;!DOCTYPE html&gt;&lt;html lang&#x3D;&quot;en&quot;&gt;&lt;head&gt; &lt;meta charset&#x3D;&quot;UTF-8&quot;&gt; &lt;meta name&#x3D;&quot;viewport&quot; content&#x3D;&quot;width&#x3D;device-width,initial-scale&#x3D;1,shrink-to-fit&#x3D;no&quot;&gt; &lt;title&gt;高级的CSS组件&lt;&#x2F;title&gt; &lt;!– Bootstrap核心css文件–&gt; &lt;link rel&#x3D;&quot;stylesheet&quot; href&#x3D;&quot;https://cdn.bootcss.com/twitter-bootstrap/4.4.1/css/bootstrap.min.css&quot;&gt;&lt;&#x2F;head&gt;&lt;body class&#x3D;&quot;container&quot;&gt;&lt;h3 class&#x3D;&quot;mb-4&quot;&gt;设置大小&lt;&#x2F;h3&gt;&lt;!–大号分页样式–&gt;&lt;ul class&#x3D;&quot;pagination pagination-lg&quot;&gt; &lt;li class&#x3D;&quot;page-item&quot;&gt;&lt;a href&#x3D;&quot;#&quot; class&#x3D;&quot;page-link&quot;&gt;首页&lt;&#x2F;a&gt;&lt;&#x2F;li&gt; &lt;li class&#x3D;&quot;page-item&quot;&gt;&lt;a href&#x3D;&quot;#&quot; class&#x3D;&quot;page-link&quot;&gt;&lt;span&gt;&amp;laquo;&lt;&#x2F;span&gt;&lt;&#x2F;a&gt;&lt;&#x2F;li&gt; &lt;li class&#x3D;&quot;page-item&quot;&gt;&lt;a href&#x3D;&quot;#&quot; class&#x3D;&quot;page-link&quot;&gt;1&lt;&#x2F;a&gt;&lt;&#x2F;li&gt; &lt;li class&#x3D;&quot;page-item&quot;&gt;&lt;a href&#x3D;&quot;#&quot; class&#x3D;&quot;page-link&quot;&gt;2&lt;&#x2F;a&gt;&lt;&#x2F;li&gt; &lt;li class&#x3D;&quot;page-item&quot;&gt;&lt;a href&#x3D;&quot;#&quot; class&#x3D;&quot;page-link&quot;&gt;3&lt;&#x2F;a&gt;&lt;&#x2F;li&gt; &lt;li class&#x3D;&quot;page-item&quot;&gt;&lt;a href&#x3D;&quot;#&quot; class&#x3D;&quot;page-link&quot;&gt;4&lt;&#x2F;a&gt;&lt;&#x2F;li&gt; &lt;li class&#x3D;&quot;page-item&quot;&gt;&lt;a href&#x3D;&quot;#&quot; class&#x3D;&quot;page-link&quot;&gt;5&lt;&#x2F;a&gt;&lt;&#x2F;li&gt; &lt;li class&#x3D;&quot;page-item&quot;&gt;&lt;a href&#x3D;&quot;#&quot; class&#x3D;&quot;page-link&quot;&gt;&lt;span&gt;&amp;raquo;&lt;&#x2F;span&gt;&lt;&#x2F;a&gt;&lt;&#x2F;li&gt; &lt;li class&#x3D;&quot;page-item&quot;&gt;&lt;a href&#x3D;&quot;#&quot; class&#x3D;&quot;page-link&quot;&gt;尾页&lt;&#x2F;a&gt;&lt;&#x2F;li&gt;&lt;&#x2F;ul&gt;&lt;!–默认分页样式–&gt;&lt;ul class&#x3D;&quot;pagination&quot;&gt; &lt;li class&#x3D;&quot;page-item&quot;&gt;&lt;a href&#x3D;&quot;#&quot; class&#x3D;&quot;page-link&quot;&gt;首页&lt;&#x2F;a&gt;&lt;&#x2F;li&gt; &lt;li class&#x3D;&quot;page-item&quot;&gt;&lt;a href&#x3D;&quot;#&quot; class&#x3D;&quot;page-link&quot;&gt;&lt;span&gt;&amp;laquo;&lt;&#x2F;span&gt;&lt;&#x2F;a&gt;&lt;&#x2F;li&gt; &lt;li class&#x3D;&quot;page-item&quot;&gt;&lt;a href&#x3D;&quot;#&quot; class&#x3D;&quot;page-link&quot;&gt;1&lt;&#x2F;a&gt;&lt;&#x2F;li&gt; &lt;li class&#x3D;&quot;page-item&quot;&gt;&lt;a href&#x3D;&quot;#&quot; class&#x3D;&quot;page-link&quot;&gt;2&lt;&#x2F;a&gt;&lt;&#x2F;li&gt; &lt;li class&#x3D;&quot;page-item&quot;&gt;&lt;a href&#x3D;&quot;#&quot; class&#x3D;&quot;page-link&quot;&gt;3&lt;&#x2F;a&gt;&lt;&#x2F;li&gt; &lt;li class&#x3D;&quot;page-item&quot;&gt;&lt;a href&#x3D;&quot;#&quot; class&#x3D;&quot;page-link&quot;&gt;4&lt;&#x2F;a&gt;&lt;&#x2F;li&gt; &lt;li class&#x3D;&quot;page-item&quot;&gt;&lt;a href&#x3D;&quot;#&quot; class&#x3D;&quot;page-link&quot;&gt;5&lt;&#x2F;a&gt;&lt;&#x2F;li&gt; &lt;li class&#x3D;&quot;page-item&quot;&gt;&lt;a href&#x3D;&quot;#&quot; class&#x3D;&quot;page-link&quot;&gt;&lt;span&gt;&amp;raquo;&lt;&#x2F;span&gt;&lt;&#x2F;a&gt;&lt;&#x2F;li&gt; &lt;li class&#x3D;&quot;page-item&quot;&gt;&lt;a href&#x3D;&quot;#&quot; class&#x3D;&quot;page-link&quot;&gt;尾页&lt;&#x2F;a&gt;&lt;&#x2F;li&gt;&lt;&#x2F;ul&gt;&lt;!–小号分页样式–&gt;&lt;ul class&#x3D;&quot;pagination pagination-sm&quot;&gt; &lt;li class&#x3D;&quot;page-item&quot;&gt;&lt;a href&#x3D;&quot;#&quot; class&#x3D;&quot;page-link&quot;&gt;首页&lt;&#x2F;a&gt;&lt;&#x2F;li&gt; &lt;li class&#x3D;&quot;page-item&quot;&gt;&lt;a href&#x3D;&quot;#&quot; class&#x3D;&quot;page-link&quot;&gt;&lt;span&gt;&amp;laquo;&lt;&#x2F;span&gt;&lt;&#x2F;a&gt;&lt;&#x2F;li&gt; &lt;li class&#x3D;&quot;page-item&quot;&gt;&lt;a href&#x3D;&quot;#&quot; class&#x3D;&quot;page-link&quot;&gt;1&lt;&#x2F;a&gt;&lt;&#x2F;li&gt; &lt;li class&#x3D;&quot;page-item&quot;&gt;&lt;a href&#x3D;&quot;#&quot; class&#x3D;&quot;page-link&quot;&gt;2&lt;&#x2F;a&gt;&lt;&#x2F;li&gt; &lt;li class&#x3D;&quot;page-item&quot;&gt;&lt;a href&#x3D;&quot;#&quot; class&#x3D;&quot;page-link&quot;&gt;3&lt;&#x2F;a&gt;&lt;&#x2F;li&gt; &lt;li class&#x3D;&quot;page-item&quot;&gt;&lt;a href&#x3D;&quot;#&quot; class&#x3D;&quot;page-link&quot;&gt;4&lt;&#x2F;a&gt;&lt;&#x2F;li&gt; &lt;li class&#x3D;&quot;page-item&quot;&gt;&lt;a href&#x3D;&quot;#&quot; class&#x3D;&quot;page-link&quot;&gt;5&lt;&#x2F;a&gt;&lt;&#x2F;li&gt; &lt;li class&#x3D;&quot;page-item&quot;&gt;&lt;a href&#x3D;&quot;#&quot; class&#x3D;&quot;page-link&quot;&gt;&lt;span&gt;&amp;raquo;&lt;&#x2F;span&gt;&lt;&#x2F;a&gt;&lt;&#x2F;li&gt; &lt;li class&#x3D;&quot;page-item&quot;&gt;&lt;a href&#x3D;&quot;#&quot; class&#x3D;&quot;page-link&quot;&gt;尾页&lt;&#x2F;a&gt;&lt;&#x2F;li&gt;&lt;&#x2F;ul&gt;
