&lt;&#x2F;head&gt;&lt;body&gt;&lt;h3 class&#x3D;&quot;mb-4&quot;&gt;旋转器颜色&lt;&#x2F;h3&gt;&lt;div class&#x3D;&quot;spinner-border text-primary&quot;&gt;&lt;&#x2F;div&gt;&lt;div class&#x3D;&quot;spinner-border text-secondary&quot;&gt;&lt;&#x2F;div&gt;&lt;div class&#x3D;&quot;spinner-border text-success&quot;&gt;&lt;&#x2F;div&gt;&lt;div class&#x3D;&quot;spinner-border text-danger&quot;&gt;&lt;&#x2F;div&gt;&lt;div class&#x3D;&quot;spinner-border text-warning&quot;&gt;&lt;&#x2F;div&gt;&lt;div class&#x3D;&quot;spinner-border text-info&quot;&gt;&lt;&#x2F;div&gt;&lt;div class&#x3D;&quot;spinner-border text-light&quot;&gt;&lt;&#x2F;div&gt;&lt;div class&#x3D;&quot;spinner-border text-dark&quot;&gt;&lt;&#x2F;div&gt;&lt;h3 class&#x3D;&quot;my-4&quot;&gt;渐变缩放颜色&lt;&#x2F;h3&gt;&lt;div class&#x3D;&quot;spinner-grow text-primary&quot;&gt;&lt;&#x2F;div&gt;&lt;div class&#x3D;&quot;spinner-grow text-secondary&quot;&gt;&lt;&#x2F;div&gt;&lt;div class&#x3D;&quot;spinner-grow text-success&quot;&gt;&lt;&#x2F;div&gt;&lt;div class&#x3D;&quot;spinner-grow text-danger&quot;&gt;&lt;&#x2F;div&gt;&lt;div class&#x3D;&quot;spinner-grow text-warning&quot;&gt;&lt;&#x2F;div&gt;&lt;div class&#x3D;&quot;spinner-grow text-info&quot;&gt;&lt;&#x2F;div&gt;&lt;div class&#x3D;&quot;spinner-grow text-light&quot;&gt;&lt;&#x2F;div&gt;&lt;div class&#x3D;&quot;spinner-grow text-dark&quot;&gt;&lt;&#x2F;div&gt;
