天气案例示例代码(监视属性)
&lt;!DOCTYPE html&gt;&lt;html&gt;	&lt;head&gt;		&lt;meta charset&#x3D;&quot;UTF-8&quot; &#x2F;&gt;		&lt;title&gt;天气案例_监视属性&lt;&#x2F;title&gt;		&lt;!– 引入Vue –&gt;		&lt;script type&#x3D;&quot;text&#x2F;javascript&quot; src&#x3D;&quot;..&#x2F;js&#x2F;vue.js&quot;&gt;&lt;&#x2F;script&gt;	&lt;&#x2F;head&gt;	&lt;body&gt;		&lt;!–				监视属性watch：					1.当被监视的属性变化时, 回调函数自动调用, 进行相关操作					2.监视的属性必须存在，才能进行监视！！					3.监视的两种写法：							(1).new Vue时传入watch配置							(2).通过vm.$watch监视		 –&gt;		&lt;!– 准备好一个容器–&gt;		&lt;div id&#x3D;&quot;root&quot;&gt;			&lt;h2&gt;今天天气很&#123;&#123;info&#125;&#125;&lt;&#x2F;h2&gt;			&lt;button @click&#x3D;&quot;changeWeather&quot;&gt;切换天气&lt;&#x2F;button&gt;		&lt;&#x2F;div&gt;	&lt;&#x2F;body&gt;
&amp;lt;script type=&amp;quot;text/javascript&amp;quot;&amp;gt;
	Vue.config.productionTip = false //阻止 vue 在启动时生成生产提示。

	const vm = new Vue(&amp;#123;
		el:&amp;#x27;#root&amp;#x27;,
		data:&amp;#123;
			isHot:true,
		&amp;#125;,
		computed:&amp;#123;
			info()&amp;#123;
				return this.isHot ? &amp;#x27;炎热&amp;#x27; : &amp;#x27;凉爽&amp;#x27;
			&amp;#125;
		&amp;#125;,
		methods: &amp;#123;
			changeWeather()&amp;#123;
				this.isHot = !this.isHot
			&amp;#125;
		&amp;#125;,
		/* watch:&amp;#123;
			isHot:&amp;#123;
				immediate:true, //初始化时让handler调用一下
				//handler什么时候调用？当isHot发生改变时。
				handler(newValue,oldValue)&amp;#123;
					console.log(&amp;#x27;isHot被修改了&amp;#x27;,newValue,oldValue)
				&amp;#125;
			&amp;#125;
		&amp;#125; */
	&amp;#125;)

	vm.$watch(&amp;#x27;isHot&amp;#x27;,&amp;#123;
		immediate:true, //初始化时让handler调用一下
		//handler什么时候调用？当isHot发生改变时。
		handler(newValue,oldValue)&amp;#123;
			console.log(&amp;#x27;isHot被修改了&amp;#x27;,newValue,oldValue)
		&amp;#125;
	&amp;#125;)
&amp;lt;/script&amp;gt;

