&lt;!DOCTYPE html&gt;&lt;html&gt;
&lt;head&gt; &lt;meta charset&#x3D;&quot;UTF-8&quot; &#x2F;&gt; &lt;title&gt;列表过滤&lt;&#x2F;title&gt; &lt;script type&#x3D;&quot;text&#x2F;javascript&quot; src&#x3D;&quot;..&#x2F;js&#x2F;vue.js&quot;&gt;&lt;&#x2F;script&gt;&lt;&#x2F;head&gt;
&lt;body&gt; &lt;!– 准备好一个容器–&gt; &lt;div id&#x3D;&quot;root&quot;&gt; &lt;h2&gt;人员列表&lt;&#x2F;h2&gt; &lt;input type&#x3D;&quot;text&quot; placeholder&#x3D;&quot;请输入名字&quot; v-model&#x3D;&quot;keyWord&quot;&gt; &lt;ul&gt; &lt;li v-for&#x3D;&quot;(p,index) of filPerons&quot; :key&#x3D;&quot;index&quot;&gt; &#123;&#123;p.name&#125;&#125;-&#123;&#123;p.age&#125;&#125;-&#123;&#123;p.sex&#125;&#125; &lt;&#x2F;li&gt; &lt;&#x2F;ul&gt; &lt;&#x2F;div&gt;
 &lt;script type&#x3D;&quot;text&#x2F;javascript&quot;&gt; Vue.config.productionTip &#x3D; false
 &#x2F;&#x2F;用watch实现 &#x2F;&#x2F;#region &#x2F;* new Vue(&#123; el:&#x27;#root&#x27;, data:&#123; keyWord:&#x27;&#x27;, persons:[ &#123;id:&#x27;001&#x27;,name:&#x27;马冬梅&#x27;,age:19,sex:&#x27;女&#x27;&#125;, &#123;id:&#x27;002&#x27;,name:&#x27;周冬雨&#x27;,age:20,sex:&#x27;女&#x27;&#125;, &#123;id:&#x27;003&#x27;,name:&#x27;周杰伦&#x27;,age:21,sex:&#x27;男&#x27;&#125;, &#123;id:&#x27;004&#x27;,name:&#x27;温兆伦&#x27;,age:22,sex:&#x27;男&#x27;&#125; ], filPerons:[] &#125;, watch:&#123; keyWord:&#123; immediate:true, handler(val)&#123; this.filPerons &#x3D; this.persons.filter((p)&#x3D;&gt;&#123; return p.name.indexOf(val) !&#x3D;&#x3D; -1 &#125;) &#125; &#125; &#125; &#125;) *&#x2F; &#x2F;&#x2F;#endregion
 &#x2F;&#x2F;用computed实现 new Vue(&#123; el: &#x27;#root&#x27;, data: &#123; keyWord: &#x27;&#x27;, persons: [&#123; id: &#x27;001&#x27;, name: &#x27;马冬梅&#x27;, age: 19, sex: &#x27;女&#x27; &#125;, &#123; id: &#x27;002&#x27;, name: &#x27;周冬雨&#x27;, age: 20, sex: &#x27;女&#x27; &#125;, &#123; id: &#x27;003&#x27;, name: &#x27;周杰伦&#x27;, age: 21, sex: &#x27;男&#x27; &#125;, &#123; id: &#x27;004&#x27;, name: &#x27;温兆伦&#x27;, age: 22, sex: &#x27;男&#x27; &#125; ] &#125;, computed: &#123; filPerons() &#123; return this.persons.filter((p) &#x3D;&gt; &#123; return p.name.indexOf(this.keyWord) !&#x3D;&#x3D; -1 &#125;) &#125; &#125; &#125;) &lt;&#x2F;script&gt;
&lt;&#x2F;html&gt;
排序操作
computed:&#123; filPerons()&#123; const arr &#x3D; this.persons.filter((p)&#x3D;&gt;&#123; return p.name.indexOf(this.keyWord) !&#x3D;&#x3D; -1 &#125;) &#x2F;&#x2F;判断一下是否需要排序 if(this.sortType)&#123; arr.sort((p1,p2)&#x3D;&gt;&#123; return this.sortType &#x3D;&#x3D;&#x3D; 1 ? p2.age-p1.age : p1.age-p2.age &#125;) &#125; return arr &#125;&#125;


