&lt;body&gt; &lt;div id&#x3D;&quot;test&quot;&gt; &lt;input type&#x3D;&quot;text&quot; v-model&#x3D;&quot;searchName&quot;&gt; &lt;ul&gt; &lt;li v-for&#x3D;&quot;(p, index) in filterPersons&quot; :key&#x3D;&quot;index&quot;&gt; &#123;&#123;index&#125;&#125;—&#123;&#123;p.name&#125;&#125;—&#123;&#123;p.age&#125;&#125; &lt;&#x2F;li&gt; &lt;&#x2F;ul&gt; &lt;button @click&#x3D;&quot;setOrderType(1)&quot;&gt;年龄升序&lt;&#x2F;button&gt; &lt;button @click&#x3D;&quot;setOrderType(2)&quot;&gt;年龄降序&lt;&#x2F;button&gt; &lt;button @click&#x3D;&quot;setOrderType(0)&quot;&gt;还原顺序&lt;&#x2F;button&gt; &lt;&#x2F;div&gt;
 &lt;script src&#x3D;&quot;..&#x2F;js&#x2F;vue.js&quot;&gt;&lt;&#x2F;script&gt;
 &lt;script&gt; new Vue(&#123; el: &#x27;#test&#x27;, data: &#123; searchName: &#x27;&#x27;, orderType: 0, &#x2F;&#x2F;0代表原本， 1代表升序， 2代表降序 persons: [&#123; name: &#x27;Tom&#x27;, age: 10 &#125;, &#123; name: &#x27;Jack&#x27;, age: 16 &#125;, &#123; name: &#x27;Rose&#x27;, age: 12 &#125;, &#123; name: &#x27;Aka&#x27;, age: 18 &#125; ] &#125;, computed: &#123; filterPersons() &#123; &#x2F;&#x2F; 1. 取出相关数据 const &#123; searchName, persons, orderType &#125; &#x3D; this; &#x2F;&#x2F; 解构赋值
 let fPersons;
 &#x2F;&#x2F; 2. 对persons进行过滤 fPersons &#x3D; persons.filter(p &#x3D;&gt; p.name.indexOf(searchName) !&#x3D;&#x3D; -1);
 &#x2F;&#x2F; 3. 排序 if (orderType !&#x3D;&#x3D; 0) &#123; fPersons.sort(function (p1, p2) &#123; &#x2F;&#x2F; 返回负数p1在前，返回正数p2在前 if (orderType &#x3D;&#x3D;&#x3D; 2) &#123; return p2.age - p1.age; &#x2F;&#x2F; 降序 &#125; else &#123; return p1.age - p2.age; &#x2F;&#x2F; 升序 &#125; &#125;) &#125; return fPersons; &#125; &#125;, methods: &#123; setOrderType(orderType) &#123; this.orderType &#x3D; orderType; &#125; &#125; &#125;) &lt;&#x2F;script&gt;&lt;&#x2F;body&gt;

事件处理在 Vue.js 中，事件处理是响应用户交互的核心功能之一。通过绑定事件监听器、使用事件修饰符和按键修饰符，可以轻松实现灵活的交互逻辑。
绑定监听在 Vue 中，通过 v-on 指令或其缩写 @ 来绑定事件监听器。例如：
&lt;button @click&#x3D;&quot;handleClick&quot;&gt;点击我&lt;&#x2F;button&gt;
在这个例子中，当用户点击按钮时，会触发 handleClick 方法。
methods: &#123; handleClick() &#123; alert(&#x27;按钮被点击了&#x27;); &#125;&#125;
事件的基本使用：
使用 v-on:xxx 或 @xxx 绑定事件，其中xxx是事件名；

例如：v-on:click 或 @click

事件的回调需要配置在methods对象中，最终会在vm上

methods中配置的函数，不要用箭头函数！否则this就不是vm了

methods中配置的函数，都是被Vue所管理的函数，this的指向是vm 或 组件实例对象；

@click=&amp;quot;demo&amp;quot; 和 @click=&amp;quot;demo($event)&amp;quot; 效果一致，但后者可以传参；


事件对象 默认事件形参: event 隐含属性对象: $event

$event 就是当前触发事件的元素，即使不传 $event，在回调函数中也可以使用 event 这个参数。

v-on:xxx&#x3D;&quot;fun&quot;@xxx&#x3D;&quot;fun&quot;@xxx&#x3D;&quot;fun(参数)&quot;


示例代码
&lt;body&gt; &lt;div id&#x3D;&quot;demo&quot;&gt; &lt;h1&gt;1. 绑定监听&lt;&#x2F;h1&gt; &lt;button @click&#x3D;&quot;test1&quot;&gt;test1&lt;&#x2F;button&gt; &lt;button @click&#x3D;&quot;test2(&#x27;abc&#x27;)&quot;&gt;test2&lt;&#x2F;button&gt; &lt;button @click&#x3D;&quot;test3&quot;&gt;test3&lt;&#x2F;button&gt; &lt;button @click&#x3D;&quot;test4(123, $event)&quot;&gt;test4&lt;&#x2F;button&gt; &lt;&#x2F;div&gt; &lt;script src&#x3D;&quot;https://cdn.bootcdn.net/ajax/libs/vue/2.6.12/vue.js&quot;&gt;&lt;/script&gt;
 &lt;script&gt; new Vue(&#123; el: &quot;#demo&quot;, data: &#123;&#125;, methods: &#123; test1() &#123; alert(&quot;hahah&quot;); &#125;, test2(msg) &#123; alert(msg); &#125;, test3(event) &#123; alert(event.target.innerHTML); &#125;, test4(number, event) &#123; alert(number + &#x27;—&#x27; + event.target.innerHTML); &#125; &#125; &#125;) &lt;&#x2F;script&gt;&lt;&#x2F;body&gt;

事件修饰符事件修饰符允许你修改事件处理程序的默认行为。这些修饰符包括 .stop, .prevent, .capture, .self, .once 等。

prevent：阻止默认事件（常用）；event.preventDefault()

stop：阻止事件冒泡（常用）；event.stopPropagation()

once：事件只触发一次（常用）；

capture：使用事件的捕获模式；

self：只有event.target是当前操作的元素时才触发事件； 

passive：事件的默认行为立即执行，无需等待事件回调执行完毕；


&lt;!DOCTYPE html&gt;&lt;html&gt;	&lt;head&gt;		&lt;meta charset&#x3D;&quot;UTF-8&quot; &#x2F;&gt;		&lt;title&gt;事件修饰符&lt;&#x2F;title&gt;		&lt;!– 引入Vue –&gt;		&lt;script type&#x3D;&quot;text&#x2F;javascript&quot; src&#x3D;&quot;..&#x2F;js&#x2F;vue.js&quot;&gt;&lt;&#x2F;script&gt;		&lt;style&gt;			*&#123;				margin-top: 20px;			&#125;			.demo1&#123;				height: 50px;				background-color: skyblue;			&#125;			.box1&#123;				padding: 5px;				background-color: skyblue;			&#125;			.box2&#123;				padding: 5px;				background-color: orange;			&#125;			.list&#123;				width: 200px;				height: 200px;				background-color: peru;				overflow: auto;			&#125;			li&#123;				height: 100px;			&#125;		&lt;&#x2F;style&gt;	&lt;&#x2F;head&gt;	&lt;body&gt;		&lt;!–				Vue中的事件修饰符：						1.prevent：阻止默认事件（常用）；						2.stop：阻止事件冒泡（常用）；						3.once：事件只触发一次（常用）；						4.capture：使用事件的捕获模式；						5.self：只有event.target是当前操作的元素时才触发事件；						6.passive：事件的默认行为立即执行，无需等待事件回调执行完毕；		–&gt;		&lt;!– 准备好一个容器–&gt;		&lt;div id&#x3D;&quot;root&quot;&gt;			&lt;h2&gt;欢迎来到&#123;&#123;name&#125;&#125;学习&lt;&#x2F;h2&gt;			&lt;!– 阻止默认事件（常用） –&gt;			&lt;a href&#x3D;&quot;http://www.baidu.com&quot; @click.prevent&#x3D;&quot;showInfo&quot;&gt;点我提示信息&lt;&#x2F;a&gt;
		&amp;lt;!-- 阻止事件冒泡（常用） 这将阻止点击事件冒泡到父元素。--&amp;gt;
		&amp;lt;div class=&amp;quot;demo1&amp;quot; @click=&amp;quot;showInfo&amp;quot;&amp;gt;
			&amp;lt;button @click.stop=&amp;quot;showInfo&amp;quot;&amp;gt;点我提示信息&amp;lt;/button&amp;gt;
			&amp;lt;!-- 修饰符可以连续写 --&amp;gt;
			&amp;lt;!-- &amp;lt;a href=&amp;quot;http://www.atguigu.com&amp;quot; @click.prevent.stop=&amp;quot;showInfo&amp;quot;&amp;gt;点我提示信息&amp;lt;/a&amp;gt; --&amp;gt;
		&amp;lt;/div&amp;gt;

		&amp;lt;!-- 事件只触发一次（常用） --&amp;gt;
		&amp;lt;button @click.once=&amp;quot;showInfo&amp;quot;&amp;gt;点我提示信息&amp;lt;/button&amp;gt;

		&amp;lt;!-- 使用事件的捕获模式 --&amp;gt;
		&amp;lt;div class=&amp;quot;box1&amp;quot; @click.capture=&amp;quot;showMsg(1)&amp;quot;&amp;gt;
			div1
			&amp;lt;div class=&amp;quot;box2&amp;quot; @click=&amp;quot;showMsg(2)&amp;quot;&amp;gt;
				div2
			&amp;lt;/div&amp;gt;
		&amp;lt;/div&amp;gt;

		&amp;lt;!-- 只有event.target是当前操作的元素时才触发事件； --&amp;gt;
		&amp;lt;div class=&amp;quot;demo1&amp;quot; @click.self=&amp;quot;showInfo&amp;quot;&amp;gt;
			&amp;lt;button @click=&amp;quot;showInfo&amp;quot;&amp;gt;点我提示信息&amp;lt;/button&amp;gt;
		&amp;lt;/div&amp;gt;

		&amp;lt;!-- 事件的默认行为立即执行，无需等待事件回调执行完毕； --&amp;gt;
		&amp;lt;ul @wheel.passive=&amp;quot;demo&amp;quot; class=&amp;quot;list&amp;quot;&amp;gt;
			&amp;lt;li&amp;gt;1&amp;lt;/li&amp;gt;
			&amp;lt;li&amp;gt;2&amp;lt;/li&amp;gt;
			&amp;lt;li&amp;gt;3&amp;lt;/li&amp;gt;
			&amp;lt;li&amp;gt;4&amp;lt;/li&amp;gt;
		&amp;lt;/ul&amp;gt;

	&amp;lt;/div&amp;gt;
&amp;lt;/body&amp;gt;

&amp;lt;script type=&amp;quot;text/javascript&amp;quot;&amp;gt;
	Vue.config.productionTip = false //阻止 vue 在启动时生成生产提示。

	new Vue(&amp;#123;
		el:&amp;#x27;#root&amp;#x27;,
		data:&amp;#123;
			name:&amp;#x27;super&amp;#x27;
		&amp;#125;,
		methods:&amp;#123;
			showInfo(e)&amp;#123;
				alert(&amp;#x27;同学你好！&amp;#x27;)
				// console.log(e.target)
			&amp;#125;,
			showMsg(msg)&amp;#123;
				console.log(msg)
			&amp;#125;,
			demo()&amp;#123;
				for (let i = 0; i &amp;lt; 100000; i++) &amp;#123;
					console.log(&amp;#x27;#&amp;#x27;)
				&amp;#125;
				console.log(&amp;#x27;累坏了&amp;#x27;)
			&amp;#125;
		&amp;#125;
	&amp;#125;)
&amp;lt;/script&amp;gt;

&lt;&#x2F;html&gt;
按键修饰符Vue 提供了按键修饰符，用于监听键盘事件，并指定响应的按键。这些修饰符包括 .enter, .tab, .delete, .esc, .space, .up, .down, .left, .right 等。
Vue中常用的按键别名：回车 &#x3D;&gt; enter删除 &#x3D;&gt; delete (捕获“删除”和“退格”键)退出 &#x3D;&gt; esc空格 &#x3D;&gt; space换行 &#x3D;&gt; tab (特殊，必须配合keydown去使用)上 &#x3D;&gt; up下 &#x3D;&gt; down左 &#x3D;&gt; left右 &#x3D;&gt; right
Vue未提供别名的按键，可以使用按键原始的key值去绑定，但注意要转为kebab-case（短横线命名）
系统修饰键（用法特殊）：ctrl、alt、shift、meta

配合keyup使用：按下修饰键的同时，再按下其他键，随后释放其他键，事件才被触发。

配合keydown使用：正常触发事件。


也可以使用keyCode去指定具体的按键（不推荐）
Vue.config.keyCodes.自定义键名 = 键码，可以去定制按键别名
&lt;!– 任何按键按下都会触发回调函数 –&gt;&lt;textarea @keyup&#x3D;&quot;testKeyup&quot;&gt;&lt;&#x2F;textarea&gt;
&lt;!– 下面的两种写法效果是一致的 –&gt;&lt;!– 使用按键码，回车键的keyCode是13 –&gt;&lt;textarea @keyup.13&#x3D;&quot;testKeyup&quot;&gt;&lt;&#x2F;textarea&gt;
&lt;!– 使用按键修饰符，因为回车键比较常用，所以vue为他设置了名称，可以直接使用enter来代替 –&gt;&lt;textarea @keyup.enter&#x3D;&quot;testKeyup&quot;&gt;&lt;&#x2F;textarea&gt;


示例代码
&lt;body&gt; &lt;div id&#x3D;&quot;demo&quot;&gt; &lt;h1&gt;3. 按键修饰符&lt;&#x2F;h1&gt; &lt;input type&#x3D;&quot;text&quot; @keyup.13&#x3D;&quot;test8&quot;&gt; &lt;input type&#x3D;&quot;text&quot; @keyup.enter&#x3D;&quot;test8&quot;&gt; &lt;&#x2F;div&gt;
 &lt;script src&#x3D;&quot;https://cdn.bootcdn.net/ajax/libs/vue/2.6.12/vue.js&quot;&gt;&lt;/script&gt;
 &lt;script&gt; new Vue(&#123; el: &quot;#demo&quot;, data: &#123;&#125;, methods: &#123; test8(event) &#123; &#x2F;&#x2F; if(event.keyCode&#x3D;&#x3D;&#x3D;13)&#123; &#x2F;&#x2F; 原来的做法 &#x2F;&#x2F; alert(event.target.value); &#x2F;&#x2F; &#125; alert(event.target.value); &#125; &#125; &#125;) &lt;&#x2F;script&gt;&lt;&#x2F;body&gt;

样式绑定在应用界面中, 某个(些)元素的样式是变化的，class&#x2F;style 绑定就是专门用来实现动态样式效果的技术
class 绑定:class&#x3D;&#x27;xxx&#x27; &#x2F;&#x2F; xxx可以是字符串、对象、数组。
字符串表达式是字符串: &amp;#39;classA&amp;#39;


适用于：类名不确定，要动态获取
&lt;!DOCTYPE html&gt;&lt;html&gt;
&lt;head&gt; &lt;meta charset&#x3D;&quot;UTF-8&quot; &#x2F;&gt; &lt;title&gt;绑定样式&lt;&#x2F;title&gt; &lt;style&gt; .basic &#123; width: 400px; height: 100px; border: 1px solid black; &#125;
 .happy &#123; border: 4px solid red; ; background-color: rgba(255, 255, 0, 0.644); background: linear-gradient(30deg, yellow, pink, orange, yellow); &#125;
 .sad &#123; border: 4px dashed rgb(2, 197, 2); background-color: gray; &#125;
 .normal &#123; background-color: skyblue; &#125;
 &lt;&#x2F;style&gt; &lt;script src&#x3D;&quot;https://cdn.bootcdn.net/ajax/libs/vue/2.6.12/vue.js&quot;&gt;&lt;/script&gt;&lt;&#x2F;head&gt;
&lt;body&gt;
 &lt;!– 准备好一个容器–&gt; &lt;div id&#x3D;&quot;root&quot;&gt; &lt;!– 绑定class样式–字符串写法，适用于：样式的类名不确定，需要动态指定 –&gt; &lt;div class&#x3D;&quot;basic&quot; :class&#x3D;&quot;mood&quot; @click&#x3D;&quot;changeMood&quot;&gt;&#123;&#123;name&#125;&#125;&lt;&#x2F;div&gt; &lt;&#x2F;div&gt;&lt;&#x2F;body&gt;
&lt;script type&#x3D;&quot;text&#x2F;javascript&quot;&gt; Vue.config.productionTip &#x3D; false
 const vm &#x3D; new Vue(&#123; el: &#x27;#root&#x27;, data: &#123; name: &#x27;YK菌&#x27;, mood: &#x27;normal&#x27; &#125;, methods: &#123; changeMood() &#123; const arr &#x3D; [&#x27;happy&#x27;, &#x27;sad&#x27;, &#x27;normal&#x27;] const index &#x3D; Math.floor(Math.random() * 3) this.mood &#x3D; arr[index] &#125; &#125;, &#125;)&lt;&#x2F;script&gt;
&lt;&#x2F;html&gt;

对象表达式是对象: &amp;#123;classA:isA, classB: isB&amp;#125;


适用于：要绑定多个样式，个数不确定，名字也不确定
对象语法用于根据条件添加或移除类名。对象的键是类名，值是布尔值，布尔值为 true 时应用该类名，为 false 时移除该类名。
&lt;div v-bind:class&#x3D;&quot;&#123; active: isActive, &#x27;text-danger&#x27;: hasError &#125;&quot;&gt;&lt;&#x2F;div&gt;


在上面的例子中，如果 isActive 为 true，active 类将被添加到 div 中。同样，如果 hasError 为 true，text-danger 类将被添加。
&lt;!DOCTYPE html&gt;&lt;html&gt;
&lt;head&gt; &lt;meta charset&#x3D;&quot;UTF-8&quot; &#x2F;&gt; &lt;title&gt;绑定样式&lt;&#x2F;title&gt; &lt;style&gt; .basic &#123; width: 400px; height: 100px; border: 1px solid black; &#125;
 .yk1 &#123; background-color: yellowgreen; &#125;
 .yk2 &#123; font-size: 30px; text-shadow: 2px 2px 10px red; &#125;
 .yk3 &#123; border-radius: 20px; &#125; &lt;&#x2F;style&gt; &lt;script src&#x3D;&quot;https://cdn.bootcdn.net/ajax/libs/vue/2.6.12/vue.js&quot;&gt;&lt;/script&gt;&lt;&#x2F;head&gt;
&lt;body&gt;
 &lt;!– 准备好一个容器–&gt; &lt;div id&#x3D;&quot;root&quot;&gt; &lt;!– 绑定class样式–数组写法，适用于：要绑定的样式个数不确定、名字也不确定 –&gt; &lt;div class&#x3D;&quot;basic&quot; :class&#x3D;&quot;classArr&quot;&gt;&#123;&#123;name&#125;&#125;&lt;&#x2F;div&gt; &lt;br &#x2F;&gt;&lt;br &#x2F;&gt; &lt;&#x2F;div&gt;&lt;&#x2F;body&gt;
&lt;script type&#x3D;&quot;text&#x2F;javascript&quot;&gt; Vue.config.productionTip &#x3D; false
 const vm &#x3D; new Vue(&#123; el: &#x27;#root&#x27;, data: &#123; name: &#x27;YK菌&#x27;, classArr: [&#x27;yk1&#x27;, &#x27;yk2&#x27;, &#x27;yk3&#x27;] &#125;, &#125;)&lt;&#x2F;script&gt;
&lt;&#x2F;html&gt;

数组表达式是数组: [&amp;#39;classA&amp;#39;, &amp;#39;classB&amp;#39;]


适用于：要绑定多个样式，个数确定，名字也确定，但不确定用不用
&lt;!DOCTYPE html&gt;&lt;html&gt;
&lt;head&gt; &lt;meta charset&#x3D;&quot;UTF-8&quot; &#x2F;&gt; &lt;title&gt;绑定样式&lt;&#x2F;title&gt; &lt;style&gt; .basic &#123; width: 400px; height: 100px; border: 1px solid black; &#125;
 .yk1 &#123; background-color: yellowgreen; &#125;
 .yk2 &#123; font-size: 30px; text-shadow: 2px 2px 10px red; &#125;
 .yk3 &#123; border-radius: 20px; &#125; &lt;&#x2F;style&gt; &lt;script src&#x3D;&quot;https://cdn.bootcdn.net/ajax/libs/vue/2.6.12/vue.js&quot;&gt;&lt;/script&gt;&lt;&#x2F;head&gt;
&lt;body&gt;
 &lt;!– 准备好一个容器–&gt; &lt;div id&#x3D;&quot;root&quot;&gt; &lt;!– 绑定class样式–对象写法，适用于：要绑定的样式个数确定、名字也确定，但要动态决定用不用 –&gt; &lt;div class&#x3D;&quot;basic&quot; :class&#x3D;&quot;classObj&quot;&gt;&#123;&#123;name&#125;&#125;&lt;&#x2F;div&gt; &lt;&#x2F;div&gt;&lt;&#x2F;body&gt;
&lt;script type&#x3D;&quot;text&#x2F;javascript&quot;&gt; Vue.config.productionTip &#x3D; false
 const vm &#x3D; new Vue(&#123; el: &#x27;#root&#x27;, data: &#123; name: &#x27;YK菌&#x27;, classObj: &#123; yk1: true, yk2: false, yk3: true &#125; &#125; &#125;)&lt;&#x2F;script&gt;
&lt;&#x2F;html&gt;

style 绑定:style&#x3D;&quot;&#123; color: activeColor, fontSize: fontSize + &#x27;px&#x27; &#125;&quot;


其中 activeColor&#x2F;fontSize 是 data 属性
:style&#x3D;&quot;&#123;fontSize: xxx&#125;&quot;其中xxx是动态值。:style&#x3D;&quot;[a,b]&quot;其中a、b是样式对象。
对象&lt;!DOCTYPE html&gt;&lt;html&gt;
&lt;head&gt; &lt;meta charset&#x3D;&quot;UTF-8&quot; &#x2F;&gt; &lt;title&gt;绑定样式&lt;&#x2F;title&gt; &lt;style&gt; .basic &#123; width: 400px; height: 100px; border: 1px solid black; &#125; &lt;&#x2F;style&gt; &lt;script src&#x3D;&quot;https://cdn.bootcdn.net/ajax/libs/vue/2.6.12/vue.js&quot;&gt;&lt;/script&gt;&lt;&#x2F;head&gt;
&lt;body&gt;
 &lt;!– 准备好一个容器–&gt; &lt;div id&#x3D;&quot;root&quot;&gt;
 &lt;!– 绑定style样式–对象写法 –&gt; &lt;div class&#x3D;&quot;basic&quot; :style&#x3D;&quot;styleObj, styleObj2&quot;&gt;&#123;&#123;name&#125;&#125;&lt;&#x2F;div&gt;
 &lt;&#x2F;div&gt;&lt;&#x2F;body&gt;
&lt;script type&#x3D;&quot;text&#x2F;javascript&quot;&gt; Vue.config.productionTip &#x3D; false
 const vm &#x3D; new Vue(&#123; el: &#x27;#root&#x27;, data: &#123; name: &#x27;YK菌&#x27;, styleObj: &#123; fontSize: &#x27;40px&#x27;, color: &#x27;red&#x27;, &#125;, styleObj2: &#123; backgroundColor: &#x27;orange&#x27; &#125;, &#125;, &#125;)&lt;&#x2F;script&gt;
&lt;&#x2F;html&gt;

数组&lt;!DOCTYPE html&gt;&lt;html&gt;
&lt;head&gt; &lt;meta charset&#x3D;&quot;UTF-8&quot; &#x2F;&gt; &lt;title&gt;绑定样式&lt;&#x2F;title&gt; &lt;style&gt; .basic &#123; width: 400px; height: 100px; border: 1px solid black; &#125; &lt;&#x2F;style&gt; &lt;script src&#x3D;&quot;https://cdn.bootcdn.net/ajax/libs/vue/2.6.12/vue.js&quot;&gt;&lt;/script&gt;&lt;&#x2F;head&gt;
&lt;body&gt;
 &lt;!– 准备好一个容器–&gt; &lt;div id&#x3D;&quot;root&quot;&gt;
 &lt;!– 绑定style样式–数组写法 –&gt; &lt;div class&#x3D;&quot;basic&quot; :style&#x3D;&quot;styleArr&quot;&gt;&#123;&#123;name&#125;&#125;&lt;&#x2F;div&gt;
 &lt;&#x2F;div&gt;&lt;&#x2F;body&gt;
&lt;script type&#x3D;&quot;text&#x2F;javascript&quot;&gt; Vue.config.productionTip &#x3D; false
 const vm &#x3D; new Vue(&#123; el: &#x27;#root&#x27;, data: &#123; name: &#x27;YK菌&#x27;, styleArr: [&#123; fontSize: &#x27;40px&#x27;, color: &#x27;blue&#x27;, &#125;, &#123; backgroundColor: &#x27;gray&#x27; &#125; ] &#125;, &#125;)&lt;&#x2F;script&gt;
&lt;&#x2F;html&gt;
